import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.DzvPB4Y-.js";const h=JSON.parse('{"title":"2D Cutting · CSP2D: Scope and Learning Path","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/csp2d/index.md","filePath":"frameworks/csp2d/index.md"}'),o={name:"frameworks/csp2d/index.md"};function r(s,e,d,l,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_2d-cutting-·-csp2d-scope-and-learning-path" tabindex="-1">2D Cutting · CSP2D: Scope and Learning Path <a class="header-anchor" href="#_2d-cutting-·-csp2d-scope-and-learning-path" aria-label="Permalink to &quot;2D Cutting · CSP2D: Scope and Learning Path&quot;">​</a></h1><p>Cut rectangular products from fixed sheets or coils while satisfying orders and process requirements. Start with fixed sheets and Freeform before coils and two-/three-stage guillotine processes.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Role</th><th>Key Fields</th></tr></thead><tbody><tr><td>Supply material</td><td><code>Material2</code></td><td>Input</td><td>Fixed width/height for sheets; no fixed height for coils</td></tr><tr><td>Product and demand</td><td><code>Product2</code> / <code>ProductDemand2</code></td><td>Input</td><td>Dimensions and demand modes such as count</td></tr><tr><td>Pattern</td><td><code>Pattern2</code></td><td>Intermediate</td><td>Placements, coverage and optional cut tree</td></tr><tr><td>Plan</td><td><code>CuttingPlan2</code></td><td>Intermediate</td><td>Material consumption and pattern use</td></tr><tr><td>Problem</td><td><code>Csp2dProblem</code></td><td>Input</td><td>Materials, products, demands, kerf, process and configuration</td></tr><tr><td>Cutting result</td><td><code>Csp2dSolution</code></td><td>Output</td><td>Pattern usage, coverage, consumed length, waste and termination</td></tr></tbody></table><p>Freeform requires valid geometry; guillotine processes also need a valid cut tree. Sheet count and consumed coil length are different objective measures.</p><div class="tip custom-block"><p class="custom-block-title">Missing Height and Cut Trees</p><p>A missing material height denotes a coil, not a zero-height sheet; each pattern still needs a segment height. A missing Freeform cut tree is valid, while guillotine patterns require a tree consistent with placements.</p></div><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Kotlin and Rust Entry Points</p><p>Kotlin uses <code>Csp2dMilp</code> / <code>Csp2dColumnGeneration</code>. Rust uses <code>Csp2dSolvers</code>, with an internal heuristic by default and an injectable <code>Csp2dMasterSolver</code>. A method named MILP does not establish that the default Rust path invokes a native MILP solver.</p></div><p>Current implementations and configuration are not fully symmetric. Start from each language&#39;s executable case rather than treating parallel snippets as a promise of identical capabilities.</p><p>Use <code>Csp2dMilp</code> / <code>solve_milp</code> to inspect a once-generated pool; use <code>Csp2dColumnGeneration</code> / <code>solve_column_generation</code> to append patterns against residual demand. This is not certified exact dual pricing; see the <a href="./business-scenario.html#entry-budget">configuration and switch</a>.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Current scope is rectangular products, not arbitrary polygon nesting.</li><li>Valid coordinates do not establish process feasibility; guillotine patterns need cut-tree validation.</li><li>Residual-demand generation or estimated-price filtering is not an LP-dual pricing certificate.</li><li>Coverage obtained by a default heuristic is not a global optimality proof.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-cutting.html">your first cutting plan</a>, starting with demand counts and plan usage.</li><li>Add kerf, then switch material mode or cutting process and check consumption and manufacturability separately.</li><li>Compare <a href="./../bpp2d/">BPP2D</a> if you only need placement of existing items.</li></ol><p>For LP, MILP, pricing and other algorithm terms, see the <a href="./../#terminology">terminology guide</a>.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-csp2d/README.md" target="_blank" rel="noreferrer">Kotlin modules and process semantics</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-csp2d/README.md" target="_blank" rel="noreferrer">Rust API, master and pricing boundaries</a></li></ul><p>Historical phase labels in the Kotlin module README may lag behind application source. These tutorials use public application APIs; implemented APIs and behavior belong in the verification reference, not capability claims inferred from phase labels.</p><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./first-cutting.html">Your First Cutting Plan</a>. Then explore <a href="./business-scenario.html">Kerf, Cutting Process and Coils</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',21)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
